Static.Script:
function buttonOnOffAction(device, online, progress, context)
{
var parDevice = device.getParameterByName("ControllerType");
var parChannelID = device.getParameterByName("ChannelIDs");
var parAction = device.getParameterByName("OnOffAction");

progress.setText("LED: Action wurde gestartet...");

var data = [1]; // internal function ID
data = data.concat([parChannelID.value]);
data = data.concat([parAction.value]);

online.connect();

var resp = online.invokeFunctionProperty(160, 6, data);
if (resp[0] != 0) {
    throw new Error("LED: Es ist ein unbekannter Fehler aufgetreten!");
}

online.disconnect();
progress.setText("LED: Aktion wurde ausgeführt.");
}
